class SmallestInfiniteSet {
    int next_num;
    set<int> added;
public:
    SmallestInfiniteSet() {
        next_num = 1;
    }

    int popSmallest() {
        if (!added.empty() && *added.begin() < next_num) {
            int smallest = *added.begin();
            added.erase(added.begin());
            return smallest;
        }
        return next_num++;
    }

    void addBack(int num) {
        if (num < next_num) {
            added.insert(num);
        }
    }
};
